# Multi-Person UWB Localization: Inference Script
# This script processes raw CIR in the shape (T, 6, 3, 120, 2)—by running
# model.tflite across sliding 64-frame windows. 
# It applies temporal smoothing to the resulting presence probabilities generating the final coordinates frame-by-frame. 
# The output is formatted:  {"frame": i, "localizations": [[x, y], ...]} in jsonl.
import argparse
import base64
import io
import json
import sys
import time
from pathlib import Path
import numpy as np
from scipy.ndimage import uniform_filter1d
import tensorflow as tf
# Configuration
RADAR_IDS   = [0, 1, 2, 3, 4, 5]
N_RADARS    = len(RADAR_IDS)
N_ANTENNAS  = 3
N_BINS_RAW  = 120
BIN_START   = 5
BIN_END     = 65
N_BINS      = BIN_END - BIN_START
WIN_FRAMES  = 64
LOW_BAND    = (1, 2)
MID_BAND    = (3, 8)
HIGH_BAND   = (9, 20)
CFAR_TRAIN  = 4
CFAR_GUARD  = 2
N_FEAT      = 6
ROOM_X, ROOM_Y = 4.8, 7.2
MAX_PEOPLE  = 4
PRESENCE_TH = 0.87   # calibrated on validation
SMOOTH_W    = 5      # presence smoothing window (frames)

#Background Template
_CALIB_B64 = ""

def _load_calibration():
    d = np.load(io.BytesIO(base64.b64decode(_CALIB_B64)))
    return d["bg"].astype(np.float32), d["mean"].astype(np.float32), d["std"].astype(np.float32)

BG_COMPLEX, NORM_MEAN, NORM_STD = _load_calibration()

# Feature extraction
def _band_energy(P, k0, k1):
    """P: (WIN, R, A, B) power spectrum of the complex FFT (full ordering).
    Sums positive band k0..k1 and the mirrored negative band."""
    pos = P[k0:k1+1].sum(axis=0)
    neg = P[WIN_FRAMES-k1:WIN_FRAMES-k0+1].sum(axis=0)
    return pos + neg

def _cfar_contrast(x):
    """CA-CFAR contrast along the last (range) axis.
    noise = mean over training cells excluding guard cells; contrast = x / noise."""
    big_n   = 2*(CFAR_TRAIN+CFAR_GUARD) + 1
    guard_n = 2*CFAR_GUARD + 1
    big   = uniform_filter1d(x, size=big_n,   axis=-1, mode='nearest') * big_n
    inner = uniform_filter1d(x, size=guard_n, axis=-1, mode='nearest') * guard_n
    noise = (big - inner) / (2*CFAR_TRAIN)
    return x / (noise + 1e-6)


def extract_features(iq_chunk):
    """iq_chunk: (WIN_FRAMES, N_RADARS, 3, 120, 2) float32 (radar-selected raw IQ).
    Returns (N_RADARS, 3, N_BINS, N_FEAT) float32."""
    res = iq_chunk - BG_COMPLEX[None]                        
    res = res[..., BIN_START:BIN_END, :]                     
    c   = res[..., 0] + 1j*res[..., 1]                       
    mag = np.abs(c)

    f_mean = mag.mean(axis=0)
    f_std  = mag.std(axis=0)

    F = np.fft.fft(c, axis=0)                                # slow-time FFT per bin
    P = (F.real**2 + F.imag**2) / WIN_FRAMES                 # power spectrum

    f_low  = np.sqrt(_band_energy(P, *LOW_BAND))
    f_mid  = np.sqrt(_band_energy(P, *MID_BAND))
    f_high = np.sqrt(_band_energy(P, *HIGH_BAND))
    f_cfar = _cfar_contrast(f_mean)

    return np.stack([f_mean, f_std, f_low, f_mid, f_high, f_cfar],
                    axis=-1).astype(np.float32)

#Inference 
def run(input_path: Path, output_path: Path) -> None:
    model_path = Path(__file__).resolve().parent / "model.tflite"
    if not model_path.exists():
        print(f"[ERROR] model.tflite not found next to code.py: {model_path}",
              file=sys.stderr)
        sys.exit(1)

    interp = tf.lite.Interpreter(model_path=str(model_path))
    interp.allocate_tensors()
    in_det, out_det   = interp.get_input_details()[0], interp.get_output_details()[0]
    in_scale, in_zp   = in_det["quantization"]
    out_scale, out_zp = out_det["quantization"]

    try:
        raw = np.load(input_path)
    except Exception as exc:
        print(f"[ERROR] Could not load input file {input_path}: {exc}", file=sys.stderr)
        sys.exit(1)
    if raw.ndim != 5 or raw.shape[1:] != (6, N_ANTENNAS, N_BINS_RAW, 2):
        print(f"[ERROR] Expected input shape (T, 6, {N_ANTENNAS}, {N_BINS_RAW}, 2), "
              f"got {raw.shape}", file=sys.stderr)
        sys.exit(1)

    T = raw.shape[0]
    n_out = T
    if T < WIN_FRAMES:   
        pad = np.repeat(raw[-1:], WIN_FRAMES - T, axis=0)
        raw = np.concatenate([raw, pad], axis=0)
        T = raw.shape[0]

    #per-frame sliding inference (stride 1, centred windows)
    all_xy   = np.zeros((n_out, MAX_PEOPLE, 2), np.float32)
    all_prob = np.zeros((n_out, MAX_PEOPLE),    np.float32)
    half = WIN_FRAMES // 2
    t0 = time.time()
    for f_idx in range(n_out):
        s = max(0, min(f_idx - half, T - WIN_FRAMES))
        feat = extract_features(raw[s:s+WIN_FRAMES, RADAR_IDS].astype(np.float32))
        feat = np.log1p(np.maximum(feat, 0))
        feat = ((feat - NORM_MEAN) / NORM_STD)[None].astype(np.float32)
        if in_scale > 0:
            q = np.clip(np.round(feat/in_scale + in_zp), -128, 127).astype(np.int8)
        else:
            q = feat
        interp.set_tensor(in_det["index"], q)
        interp.invoke()
        out = interp.get_tensor(out_det["index"]).astype(np.float32)
        if out_scale > 0:
            out = (out - out_zp) * out_scale
        out = out.reshape(MAX_PEOPLE, 3)
        all_xy[f_idx]   = out[:, :2]
        all_prob[f_idx] = 1.0/(1.0 + np.exp(-out[:, 2]))
        if f_idx % 1000 == 0:
            print(f"  frame {f_idx}/{n_out}  ({time.time()-t0:.0f}s)")
    print(f"Inference pass done in {time.time()-t0:.0f}s")

    # temporal smoothing of the presence probabilities per slot
    if SMOOTH_W > 1:
        probs_s = uniform_filter1d(all_prob, size=SMOOTH_W, axis=0, mode="nearest")
    else:
        probs_s = all_prob

    # decoding with the validation-calibrated threshold, clip to room
    with open(output_path, "w") as fh:
        for f_idx in range(n_out):
            locs = []
            for j in range(MAX_PEOPLE):
                if probs_s[f_idx, j] >= PRESENCE_TH:
                    x = float(np.clip(all_xy[f_idx, j, 0], 0.0, ROOM_X))
                    y = float(np.clip(all_xy[f_idx, j, 1], 0.0, ROOM_Y))
                    locs.append([round(x, 6), round(y, 6)])
            fh.write(json.dumps({"frame": f_idx, "localizations": locs}) + chr(10))
    print(f"Wrote {n_out} frames -> {output_path}")

def main() -> None:
    p = argparse.ArgumentParser(description="Multi-person UWB localization inference")
    p.add_argument("--input-path",  required=True, help="Raw CIR .npy file (T, 6, 3, 120, 2)")
    p.add_argument("--output-path", required=True, help="Destination .jsonl predictions file")
    a = p.parse_args()
    run(Path(a.input_path), Path(a.output_path))

if __name__ == "__main__":
    main()